0:
.:1053 {
  errors
  log
  health {
    lameduck 5s
  }
  ready

  k8s_gateway ${ORG_DOMAIN} ${XYZ_DOMAIN} ${NET_DOMAIN} {
    apex  k8s-gateway.network
    resources Ingress Service
    ttl 300
  }

  prometheus 0.0.0.0:9153
  loop
  reload
  loadbalance
}

1:
.:1053 {
  k8s_gateway rx.cz {
    apex k8s-gateway.network
    resources Ingress
    ttl 1
  }
  errors
  health {
    lameduck 5s
  }
  ready
  prometheus 0.0.0.0:9153
  forward . /etc/resolv.conf
  cache 30
  loop
  reload
  loadbalance
}
storage.rx.cz:1053 {
  errors
  forward . 192.168.1.19
  cache 30
}
